import{_ as o,o as t,c as a,ae as c}from"./chunks/framework.Dn44qsu3.js";const q=JSON.parse('{"title":"FAQ","description":"","frontmatter":{},"headers":[],"relativePath":"faq.md","filePath":"faq.md"}'),d={name:"faq.md"};function r(n,e,s,u,i,p){return t(),a("div",null,[...e[0]||(e[0]=[c('<h1 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ&quot;">​</a></h1><h2 id="q1-new-function-动态执行有什么安全与兼容性约束" tabindex="-1">Q1：<code>new Function</code> 动态执行有什么安全与兼容性约束？ <a class="header-anchor" href="#q1-new-function-动态执行有什么安全与兼容性约束" aria-label="Permalink to &quot;Q1：`new Function` 动态执行有什么安全与兼容性约束？&quot;">​</a></h2><p><code>new Function</code> 属于 eval 类动态执行，依赖 CSP 的 <code>unsafe-eval</code> 授权——启用严格 <code>script-src</code>（不含 <code>unsafe-eval</code>）的站点无法使用。同时，<strong>vjson 来源即代码来源</strong>：<code>scriptSetup</code> 中的代码会被原样执行，因此 vjson 必须只来自可信的管控端（数据库、内部接口），严禁直接接受终端用户提交的 vjson，否则等同于开放任意 JS 执行。</p><h2 id="q2-组件缓存机制是怎样的" tabindex="-1">Q2：组件缓存机制是怎样的？ <a class="header-anchor" href="#q2-组件缓存机制是怎样的" aria-label="Permalink to &quot;Q2：组件缓存机制是怎样的？&quot;">​</a></h2><p>编译结果以 <code>vjson.name</code> 为 key 缓存，value 中同时记录 vjson 的 JSON 字符串。同一 <code>name</code> 内容不变时直接复用组件实例（避免重复编译）；内容变化时自动重新编译，天然支持运行时热更新。<code>name</code> <strong>必须唯一</strong>——不同业务组件重名会互相覆盖缓存。可通过 <code>recompileVjson</code> 显式触发重编译。</p><h2 id="q3-表达式写错了会怎样" tabindex="-1">Q3：表达式写错了会怎样？ <a class="header-anchor" href="#q3-表达式写错了会怎样" aria-label="Permalink to &quot;Q3：表达式写错了会怎样？&quot;">​</a></h2><p>所有动态表达式（<code>:prop</code>、<code>v-if</code>、<code>v-for</code> 数据源、v-model 读写端等）均被 <code>resolveEepress</code> / <code>resolveEepressSet</code> / <code>withVfor</code> 包裹 try/catch 容错：单个表达式异常只会导致<strong>该属性/该节点不渲染</strong>（返回 <code>undefined</code>），不会打断整页渲染；开发态会在控制台输出 <code>[vjson]</code> 前缀的警告辅助定位。生产环境错误静默为 <code>undefined</code>，请务必在 DEV 环境排查。</p><h2 id="q4-为什么-el-button-的-type-primary-要写成-type-primary" tabindex="-1">Q4：为什么 <code>el-button</code> 的 <code>type=&quot;primary&quot;</code> 要写成 <code>&quot;:type&quot;: &quot;&#39;primary&#39;&quot;</code>？ <a class="header-anchor" href="#q4-为什么-el-button-的-type-primary-要写成-type-primary" aria-label="Permalink to &quot;Q4：为什么 `el-button` 的 `type=&quot;primary&quot;` 要写成 `&quot;:type&quot;: &quot;&#39;primary&#39;&quot;`？&quot;">​</a></h2><p><code>type</code>/<code>key</code>/<code>name</code>/<code>slot</code>/<code>children</code> 是 vjson 保留字段。组件自身属性与保留字段同名时（<code>el-button</code> 的 <code>type</code>、<code>input</code> 的 <code>type</code> 等），必须用 <code>&quot;:type&quot;</code> 动态绑定字面量表达式的形式，否则会被引擎当作组件类型解析，导致渲染异常。</p><h2 id="q5-支持事件修饰符-stop-prevent-吗" tabindex="-1">Q5：支持事件修饰符（<code>.stop</code> / <code>.prevent</code>）吗？ <a class="header-anchor" href="#q5-支持事件修饰符-stop-prevent-吗" aria-label="Permalink to &quot;Q5：支持事件修饰符（`.stop` / `.prevent`）吗？&quot;">​</a></h2><p>暂不支持。需要阻断冒泡/默认行为时，请在 handler 中使用 <code>$event.stopPropagation()</code> / <code>$event.preventDefault()</code>。</p><h2 id="q6-调试时如何定位动态代码" tabindex="-1">Q6：调试时如何定位动态代码？ <a class="header-anchor" href="#q6-调试时如何定位动态代码" aria-label="Permalink to &quot;Q6：调试时如何定位动态代码？&quot;">​</a></h2><p>引擎为生成的组件代码注入了 <code>//# sourceURL=vjson://{name}.js</code>，DevTools 中可按 vjson 组件名定位到动态生成的源码；编译失败时错误信息会包含组件名与原始报错堆栈。</p><h2 id="q7-性能有什么需要权衡的" tabindex="-1">Q7：性能有什么需要权衡的？ <a class="header-anchor" href="#q7-性能有什么需要权衡的" aria-label="Permalink to &quot;Q7：性能有什么需要权衡的？&quot;">​</a></h2><p>编译期成本转移到了运行期：首次渲染需要拼串 + <code>new Function</code> 编译（有组件缓存兜底）；每次 patch 时动态表达式以闭包求值并伴随 try/catch，大列表高频更新场景存在额外开销。建议：高频变化的大列表尽量下沉为静态组件、vjson 只描述结构骨架，并对编译结果做好缓存复用。</p><h2 id="q8-如何在-scriptsetup-中使用-vue-router" tabindex="-1">Q8：如何在 scriptSetup 中使用 vue-router？ <a class="header-anchor" href="#q8-如何在-scriptsetup-中使用-vue-router" aria-label="Permalink to &quot;Q8：如何在 scriptSetup 中使用 vue-router？&quot;">​</a></h2><p>在宿主应用安装 vue-router 后，调用 core 导出的 <code>registerRouterApi({ useRouter, useRoute })</code> 注册；之后动态代码中即可通过 <code>router</code> / <code>route</code> 使用路由能力。未注册时 <code>router</code>/<code>route</code> 为 <code>undefined</code> 占位，不影响编译。</p>',17)])])}const h=o(d,[["render",r]]);export{q as __pageData,h as default};
